// The webhook payload lands under .body; tolerate both shapes.
const r = $json.body ?? $json;
const s = r.summary ?? {};
const f = r.failures ?? [];

const esc = (v) => String(v ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const th = 'padding:7px 10px;border-bottom:2px solid #333;text-align:left';
const td = 'padding:7px 10px;border-bottom:1px solid #eee';

const rows = f.map((x) =>
  `<tr><td style="${td}"><b>${esc(x.what)}</b><br><span style="color:#888;font-size:12px">${esc(x.url)}</span></td>` +
  `<td style="${td};color:#c0392b">${esc(x.error)}</td>` +
  `<td style="${td};color:#888">${esc(x.server)}</td></tr>`).join('');

const formLine = s.forms
  ? `, ${s.formsAccepted ?? s.formsOk}/${s.forms} lead form${s.forms === 1 ? '' : 's'} accepted a test submission` + (s.formsOk === s.forms ? ' and all confirmed in the CRM' : `, ${s.formsOk} confirmed in the CRM`)
  : '';

const body = r.healthy
  ? `<p>All <b>${s.sites}</b> hostnames answered${formLine}.</p>`
  : `<p><b style="color:#c0392b">${f.length} failing</b> of ${s.sites} hostnames${formLine}.</p>
     <table style="border-collapse:collapse;width:100%;font-size:13px">
       <thead><tr><th style="${th}">What</th><th style="${th}">Problem</th><th style="${th}">Server</th></tr></thead>
       <tbody>${rows}</tbody>
     </table>`;

const html = `<div style="font:14px/1.6 system-ui,-apple-system,'Segoe UI',sans-serif;color:#222;max-width:680px">
  <h2 style="margin:0 0 4px">KW Estate — outside-in check</h2>
  <p style="margin:0 0 18px;color:#888;font-size:13px">${esc(r.at)} · ${s.sites} hostnames · slowest response ${s.slowestMs ?? 0} ms${r.reason ? " · " + esc(r.reason) : ""}</p>
  ${body}
  <p style="margin-top:22px;font-size:12px;color:#aaa">
    Sent by the KW Estate dashboard on ${esc(r.from || "an unknown host")}. Full detail at
    <a href="https://estate.leadq.co.in" style="color:#0d9c8a">estate.leadq.co.in</a>.
  </p>
</div>`;

return [{ json: { to: r.to, cc: r.cc ?? '', subject: r.subject, html, healthy: r.healthy === true } }];

const req = $('Verify webhook').first().json.body ?? {};
const phone = String(req.phone ?? '').replace(/\D/g, '').slice(-10);
const date = String(req.date ?? '').trim();
const res = $json ?? {};

// An IP-allowlist rejection nests the real reply as a JSON STRING inside
// `data`. Unwrap before deciding, or a hard refusal reads as no such lead.
let body = res;
if (typeof res?.data === 'string') {
  try { body = JSON.parse(res.data.trim()); } catch { body = { error: res.data.trim() }; }
}

const err = body?.error ?? body?.Error ?? (Array.isArray(body) ? body[0]?.error : null);

// Cratio reports an empty result as an ERROR: NO RECORDS FOUND. That is an
// answer, not a failure, and treating it as one inverted the entire point.
const isEmptyResult = err && /no\s*records?\s*found/i.test(String(err));

if (err && !isEmptyResult) {
  return [{ json: { result: 'LEAD_ERROR', checked: phone, detail: String(err).slice(0, 200) } }];
}

// The number is the same every day so the CRM updates one lead instead of
// piling up a new one each morning. That makes "a lead with this number
// exists" useless as proof — it would be true even if today's submission
// never arrived. The date carried in the contact name is what makes the
// answer about TODAY.
const blob = JSON.stringify(body);
const hasPhone = phone.length === 10 && blob.replace(/\D/g, '').includes(phone);
const hasToday = date ? blob.includes(date) : true;
const found = !isEmptyResult && hasPhone && hasToday;

return [{ json: {
  result: found ? 'LEAD_FOUND' : 'LEAD_MISSING',
  checked: phone,
  date,
  by: found ? (hasToday && date ? 'number and today\'s date present' : 'number present') : undefined,
  why: found ? undefined : (!hasPhone ? 'the number is not in the reply' : 'found the lead, but not updated today'),
  detail: found ? undefined : blob.slice(0, 200),
} }];
